from pathlib import Path
import base64,gzip
DATA=""
Path("site/app.js").write_bytes(gzip.decompress(base64.b64decode(DATA)))
print("site/app.js generated")


# HAT_PATCH_V2: expose dashboard state, correct Hemat scaling, and notify extension analytics.
p=Path("site/app.js")
s=p.read_text(encoding="utf-8")
s=s.replace(
"function autoScale(v){const x=Math.abs(convertAmount(v));if(x>=1e12)return 1e12;if(x>=1e9)return 1e9;if(x>=1e6)return 1e6;return 1}",
"function autoScale(v){const x=Math.abs(convertAmount(v));const h=state.currency==='toman'?1e12:1e13;if(x>=h)return h;if(x>=1e9)return 1e9;if(x>=1e6)return 1e6;return 1}"
)
s=s.replace(
"function resolvedScale(v=0,override=null){if(override)return override;return state.scale==='auto'?autoScale(v):+state.scale}",
"function resolvedScale(v=0,override=null){if(override)return override;if(state.scale==='hemat')return state.currency==='toman'?1e12:1e13;return state.scale==='auto'?autoScale(v):+state.scale}"
)
s=s.replace(
"function scaleName(sc){return sc===1e12?'همت':sc===1e9?'میلیارد':sc===1e6?'میلیون':''}",
"function scaleName(sc){const h=state.currency==='toman'?1e12:1e13;return sc===h?'همت':sc===1e9?'میلیارد':sc===1e6?'میلیون':''}"
)
s=s.replace(
"$('#scaleFilter').addEventListener('change',e=>{state.scale=e.target.value==='auto'?'auto':+e.target.value;renderAll()});",
"$('#scaleFilter').addEventListener('change',e=>{state.scale=e.target.value==='auto'?'auto':(e.target.value==='hemat'?'hemat':+e.target.value);renderAll()});"
)
needle="const state={year:initialYear,brands:[],months:[],search:'',currency:'rial',scale:'auto',tab:'overview',selectedSku:null,rawSource:'sku',rawPage:1,rawPageSize:25,sortKey:null,sortDir:1,skuRankSearch:'',skuRankBrand:'',skuRankSort:'value',skuRankSortDir:-1,skuRankPage:1,skuRankPageSize:25};"
s=s.replace(needle,needle+"window.HAT_DATA=D;window.HAT_STATE=state;")
old="function renderAll(){syncMultiUI();renderKPIs();renderTrend();renderBrandBars();renderDonut();renderInsights();renderHeatmap();renderBrandRanking();renderMom();renderSku();renderRaw()}"
new="function renderAll(){syncMultiUI();renderKPIs();renderTrend();renderBrandBars();renderDonut();renderInsights();renderHeatmap();renderBrandRanking();renderMom();renderSku();renderRaw();window.dispatchEvent(new CustomEvent('hatfilters'))}"
s=s.replace(old,new)
p.write_text(s,encoding="utf-8")
print("site/app.js patched for analytics v2")
